import loggingfrom functools import wrapsfrom typing import Any, Callable, Dict, Optionaldef log(filename: Optional[str] = None) -> Callable[[Callable[..., Any]], Callable[..., Any]]:    """    Декоратор для логирования начала и конца выполнения функции, а также её результатов или возникших ошибок.    Если filename задан, логи записываются в указанный файл.    Если filename не задан, логи выводятся в консоль.    """    def decorator(func: Callable[..., Any]) -> Callable[..., Any]:        @wraps(func)        def wrapper(*args: Any, **kwargs: Dict[Any, Any]) -> Any:            # Начало выполнения функции            print(f"Начало выполнения функции {func.__name__}")            try:                result = func(*args, **kwargs)                if filename:                    logging.basicConfig(filename=filename, level=logging.INFO)                    logger = logging.getLogger()                    logger.info(f"{func.__name__} ok")                    return result                else:                    print("Функция выполнена успешно")                    return result            except Exception as e:                if filename:                    logging.basicConfig(filename=filename, level=logging.ERROR)                    logger = logging.getLogger()                    logger.error(f"{func.__name__} завершилась с ошибкой: {e}")                    logger.exception(e)                    raise e                else:                    print(f"{func.__name__} завершилась с ошибкой: {e}")                    raise e            finally:                print(f"Конец выполнения функции {func.__name__}\n")        return wrapper    return decorator@log()  # Логирование в консольdef function(arg1, arg2):    print("функция выполнена")    return arg1 + arg2# def checking_that_arg_is(predicate, error_message):#     def wrapper(function):#         def inner(arg):#             if not predicate(arg):#                 raise Val